+    return "127.0.0.1";
+  }
+
+  public int dnsDomainLevels(String host) {
+    return host.split("\\.").length - 1;
+  }
+
+  public boolean shExpMatch(String str, String shexp) {
+    String exp = shexp.replace("*", "");
+    return Pattern.compile(exp).matcher(str).find();
+  }
